plugins {
	id("java-library-conventions")
	id("io.spring.dependency-management")
}

version = "0.0.1-SNAPSHOT"

dependencies {
	// Jackson 2 annotations are part of the public polymorphic types in this module.
	// Jackson 3 databind annotations are generated by Lombok @Jacksonized (see lombok.config).
	// Exposed as api so consumers can compile against both annotation types.
	// Versions come from the Spring Boot 4 BOM: Jackson 2 annotations stay readable by Jackson 3,
	// and the Jackson 3 databind version matches the app's runtime.
	api("com.fasterxml.jackson.core:jackson-databind")
	api("tools.jackson.core:jackson-databind")
}

dependencyManagement {
	imports {
		mavenBom(org.springframework.boot.gradle.plugin.SpringBootPlugin.BOM_COORDINATES)
	}
}